package railway.ai;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * Represents a single real-time event generated by the local AI passenger swarm.
 * Tracks bookings, waiting list assignments, cancellations, and promotions with Quota info.
 */
public class AiEvent {
    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("HH:mm:ss");

    private final long id;
    private final String timestamp;
    private final String eventType; // BOOKING_CONFIRMED, WAITING_LIST, CANCELLED, TATKAL_RUSH_START, etc.
    private final String botName;
    private final int botAge;
    private final String trainNumber;
    private final String trainName;
    private final String ticketClass;
    private final String quota; // "GENERAL" or "TATKAL"
    private final int seatCount;
    private final String pnr;
    private final String detail;

    public AiEvent(long id, String eventType, String botName, int botAge,
                   String trainNumber, String trainName, String ticketClass,
                   int seatCount, String pnr, String detail) {
        this(id, eventType, botName, botAge, trainNumber, trainName, ticketClass, "GENERAL", seatCount, pnr, detail);
    }

    public AiEvent(long id, String eventType, String botName, int botAge,
                   String trainNumber, String trainName, String ticketClass,
                   String quota, int seatCount, String pnr, String detail) {
        this.id = id;
        this.timestamp = LocalDateTime.now().format(TIME_FORMAT);
        this.eventType = eventType;
        this.botName = botName;
        this.botAge = botAge;
        this.trainNumber = trainNumber;
        this.trainName = trainName;
        this.ticketClass = ticketClass;
        this.quota = quota != null ? quota.toUpperCase() : "GENERAL";
        this.seatCount = seatCount;
        this.pnr = pnr;
        this.detail = detail;
    }

    public long getId() { return id; }
    public String getTimestamp() { return timestamp; }
    public String getEventType() { return eventType; }
    public String getBotName() { return botName; }
    public int getBotAge() { return botAge; }
    public String getTrainNumber() { return trainNumber; }
    public String getTrainName() { return trainName; }
    public String getTicketClass() { return ticketClass; }
    public String getQuota() { return quota; }
    public boolean isTatkal() { return "TATKAL".equalsIgnoreCase(quota); }
    public int getSeatCount() { return seatCount; }
    public String getPnr() { return pnr; }
    public String getDetail() { return detail; }

    public String toJson() {
        return String.format(
            "{\"id\":%d,\"timestamp\":\"%s\",\"eventType\":\"%s\",\"botName\":\"%s\",\"botAge\":%d,\"trainNumber\":\"%s\",\"trainName\":\"%s\",\"ticketClass\":\"%s\",\"quota\":\"%s\",\"isTatkal\":%b,\"seatCount\":%d,\"pnr\":\"%s\",\"detail\":\"%s\"}",
            id, escape(timestamp), escape(eventType), escape(botName), botAge,
            escape(trainNumber), escape(trainName), escape(ticketClass), escape(quota), isTatkal(),
            seatCount, escape(pnr != null ? pnr : ""), escape(detail)
        );
    }

    private static String escape(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", " ").replace("\r", "");
    }
}
